import { constants } from 'node:fs';
import { open } from 'node:fs/promises';
import { join } from 'node:path';

import type { BibleImportSuggestion } from '../../shared/ipc-contract';
import { bibleTranslationInputSchema } from './bible-translation-input';

/**
 * Every eBible.org USFM download carries this page, generated by its
 * publishing tool (Haiola) in one layout: the translation's title, language,
 * eBible.org address, copyright line and licence.
 */
export const COPYRIGHT_PAGE = 'copr.htm';
const MAX_PAGE_BYTES = 512 * 1024;

/**
 * Suggests the translation's details from the folder's eBible.org copyright
 * page. A folder without one, or a page in another layout, suggests nothing,
 * and the administrator types the details instead.
 */
export async function readSuggestedDetails(
  directory: string,
): Promise<BibleImportSuggestion> {
  const page = await readCopyrightPage(join(directory, COPYRIGHT_PAGE));
  return page === null ? {} : parseEbibleCopyrightPage(page);
}

/**
 * Reads the page's details as plain text. The page is untrusted: nothing in
 * it is rendered, only text is taken out of it, and each detail is kept only
 * when it is valid for the server.
 */
export function parseEbibleCopyrightPage(html: string): BibleImportSuggestion {
  const title = textOf(match(html, /<title[^>]*>([\s\S]*?)<\/title>/i));
  // The credit is built from the name, so it needs a name the server accepts.
  const name = bibleTranslationInputSchema.shape.name.safeParse(title).success
    ? title
    : undefined;
  const languageCode = match(
    html,
    /<html\b[^>]*\blang\s*=\s*["']([^"']+)["']/i,
  );
  const sourceUrl = match(
    html,
    /<div\s+class\s*=\s*["']toc["'][^>]*>\s*<a\s[^>]*\bhref\s*=\s*["']([^"']+)["']/i,
  );
  const copyright = textOf(
    match(
      html,
      /<div\s+class\s*=\s*["']copyright["'][^>]*>[\s\S]*?<p\b[^>]*>\s*<a\b[^>]*>([\s\S]*?)<\/a>\s*<\/p>/i,
    ),
  );
  const licenceTerms = licenceTermsOf(html);

  return keepValid({
    code: codeOf(sourceUrl),
    name,
    languageCode,
    licence: [copyright, licenceTerms].filter(Boolean).join('\n') || undefined,
    attribution: name && copyright ? `${name} (${copyright})` : undefined,
    sourceUrl: sourceUrl?.trim(),
  });
}

/** The translation's eBible.org identifier (`eng-web`) as a code (`ENGWEB`). */
function codeOf(sourceUrl: string | undefined): string | undefined {
  if (!sourceUrl) return undefined;
  let url: URL;
  try {
    url = new URL(sourceUrl);
  } catch {
    return undefined;
  }
  if (!/(^|\.)ebible\.org$/i.test(url.hostname)) return undefined;
  const identifier = url.pathname.split('/').filter(Boolean).at(-1);
  return identifier?.replace(/[^A-Za-z0-9]/g, '').toUpperCase();
}

/** The sentence naming the licence, with the licence's address. */
function licenceTermsOf(html: string): string | undefined {
  const paragraph =
    /<p\b[^>]*>((?:(?!<\/?p\b)[\s\S])*?under the terms of(?:(?!<\/?p\b)[\s\S])*?)<\/p>/i.exec(
      html,
    )?.[1];
  if (!paragraph) return undefined;
  const sentence = textOf(paragraph);
  const address = match(paragraph, /<a\s[^>]*\bhref\s*=\s*["']([^"']+)["']/i);
  return address && sentence ? `${sentence} ${address}` : sentence;
}

function keepValid(
  candidate: Record<keyof BibleImportSuggestion, string | undefined>,
): BibleImportSuggestion {
  const fields = bibleTranslationInputSchema.shape;
  const suggestion: Record<string, string> = {};
  for (const key of Object.keys(candidate) as Array<
    keyof BibleImportSuggestion
  >) {
    const value = candidate[key];
    if (value !== undefined && fields[key].safeParse(value).success) {
      suggestion[key] = value;
    }
  }
  return suggestion;
}

function match(text: string, pattern: RegExp): string | undefined {
  return pattern.exec(text)?.[1];
}

const NAMED_ENTITIES: Record<string, string> = {
  amp: '&',
  lt: '<',
  gt: '>',
  quot: '"',
  apos: "'",
  nbsp: ' ',
  copy: '©',
};

/** An HTML fragment's text: tags dropped, entities decoded, spaces collapsed. */
function textOf(fragment: string | undefined): string | undefined {
  if (fragment === undefined) return undefined;
  const text = fragment
    .replace(/<[^>]*>/g, ' ')
    .replace(/&(#x[0-9a-f]+|#[0-9]+|[a-z]+);/gi, (entity, body: string) => {
      if (body.startsWith('#')) {
        const codePoint =
          body[1]?.toLowerCase() === 'x'
            ? Number.parseInt(body.slice(2), 16)
            : Number.parseInt(body.slice(1), 10);
        return codePoint > 0 && codePoint <= 0x10ffff
          ? String.fromCodePoint(codePoint)
          : ' ';
      }
      return NAMED_ENTITIES[body.toLowerCase()] ?? entity;
    })
    .replace(/\s+/g, ' ')
    .trim();
  return text || undefined;
}

/**
 * Reads the page through a single handle, never following a link, and gives
 * up on one too large to be a copyright page.
 */
async function readCopyrightPage(path: string): Promise<string | null> {
  let handle;
  try {
    handle = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
  } catch {
    return null;
  }
  try {
    const details = await handle.stat();
    if (!details.isFile() || details.size > MAX_PAGE_BYTES) return null;
    return await handle.readFile('utf8');
  } finally {
    await handle.close();
  }
}
